file.content:
                    "issuer_did": issuer_did,
                    "credential_id": credential_id,
                    "events": [
                        {
                            "status": event.status,
                            "reason": event.reason,
                            "updated_at": event.updated_at,
                            "issuer_key_version": event.issuer_key_version,
                            "audit_seq": event.audit_seq,
                            "audit_timestamp": event.audit_timestamp,
                            "cursor": event.cursor,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        def _get_audit(self, tenant: str, query: str) -> None:            # GET /v1/audit?limit=&after=：租户内按 seq 升序。
            # limit 缺省 50，须为 1..200 的整数；after 缺省 0，须为
            # 非负整数；非法一律 400。返回 events 与 next_after，
            # 空页 next_after 保持 after。
            params = parse_qs(query, keep_blank_values=True)
            limit_values = params.get("limit")
            after_values = params.get("after")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError("查询参数 limit 须在 1 到 200 之间")
            else:
                limit = 50
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_audit(tenant, after, limit)
            self._send_json(
                200,
                {
                    "events": [
                        {
                            "seq": event.seq,
                            "timestamp": event.timestamp,
                            "tenant_id": event.tenant_id,
                            "action": event.action,
                            "resource_type": event.resource_type,
                            "resource_id": event.resource_id,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        # 审计清单事件固定六字段（与 GET /v1/audit 完全一致）。
        _AUDIT_EVENT_FIELDS = (
            "seq",
            "timestamp",
            "tenant_id",
            "action",
            "resource_type",
            "resource_id",
        )

        def _audit_event_obj(self, event: Any) -> Dict[str, Any]:
            return {
                "seq": event.seq,
                "timestamp": event.timestamp,
                "tenant_id": event.tenant_id,
                "action": event.action,
                "resource_type": event.resource_type,
                "resource_id": event.resource_id,
            }

        def _parse_audit_manifest_query(
            self, query: str
        ) -> Dict[str, Any]:
            # 仅允许 snapshot、signer_did、after、limit，各一次。
            # snapshot 必填非负整数；signer_did 必填非空串；after 缺省
            # 0 且非负；limit 缺省 50 且限 1..200；after 不得大于
            # snapshot。任何空值、重复、未知参数、非 ASCII 数字、符号、
            # 小数均抛 ValidationError（400，仅含非空中文 error）。
            params = parse_qs(query, keep_blank_values=True)
            allowed = {"snapshot", "signer_did", "after", "limit"}
            unknown = sorted(set(params) - allowed)
            if unknown:
                raise ValidationError(
                    f"不支持的查询参数: {', '.join(unknown)}"
                )

            def _single(name: str) -> Optional[str]:
                values = params.get(name)
                if values is None:
                    return None
                if len(values) != 1:
                    raise ValidationError(
                        f"查询参数 {name} 只能提供一次"
                    )
                return values[0]

            snapshot_raw = _single("snapshot")
            if snapshot_raw is None:
                raise ValidationError("查询参数 snapshot 必填")
            snapshot = _parse_nonneg_int(snapshot_raw, "snapshot")

            signer_did = _single("signer_did")
            if signer_did is None or not signer_did:
                raise ValidationError(
                    "查询参数 signer_did 必填且必须为非空字符串"
                )

            after_raw = _single("after")
            after = (
                _parse_nonneg_int(after_raw, "after")
                if after_raw is not None
                else 0
            )

            limit_raw = _single("limit")
            if limit_raw is not None:
                limit = _parse_nonneg_int(limit_raw, "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            if after > snapshot:
                raise ValidationError(
                    "查询参数 after 不得大于 snapshot"
                )

            return {
                "snapshot": snapshot,
                "after": after,
                "limit": limit,
                "signer_did": signer_did,
            }

        def _get_audit_manifest(self, tenant: str, query: str) -> None:
            # GET /v1/audit/manifest：生成 snapshot 时刻（含）之前一页
            # 审计事件的签名清单。200 键序固定为 snapshot、after、limit、
            # count、events、signer_did、key_version、signature；events
            # 保留审计事件完整六字段并按 seq 升序；signature 由签名
            # DID 当前版本私钥对除 signature 外七键规范化 JSON 做 ES256
            # 裸 R||S 无填充 base64url 签名。纯只读、不记审计。
            args = self._parse_audit_manifest_query(query)

            # snapshot 越界（400）优先于签名 DID 的 404/409 判定。
            events = store.list_audit_until(
                tenant,
                args["after"],
                args["limit"],
                args["snapshot"],
            )

            signer_did = args["signer_did"]
            key_version, private_pem = store.get_audit_manifest_signer(
                tenant, signer_did
            )

            event_objs = [self._audit_event_obj(event) for event in events]
            signed = {
                "snapshot": args["snapshot"],
                "after": args["after"],
                "limit": args["limit"],
                "count": len(event_objs),
                "events": event_objs,
                "signer_did": signer_did,
                "key_version": key_version,
            }
            manifest = dict(signed)
            manifest["signature"] = crypto.sign(signed, private_pem)
            self._send_json(200, manifest)

        def _audit_manifest_is_well_formed(self, manifest: Any) -> bool:
            # 清单结构校验（阶段一“清单非法”）：恰含八键且类型/取值
            # 合法；events 每项恰为审计事件六字段，seq 严格递增且均在
            # (after, snapshot] 区间，count 与事件数一致。
            if not isinstance(manifest, dict):
                return False
            expected = {
                "snapshot",
                "after",
                "limit",
                "count",
                "events",
                "signer_did",
                "key_version",
                "signature",
            }
            if set(manifest) != expected:
                return False

            def _is_int(value: Any) -> bool:
                return isinstance(value, int) and not isinstance(value, bool)

            if not _is_int(manifest["snapshot"]) or manifest["snapshot"] < 0:
                return False
            if not _is_int(manifest["after"]) or manifest["after"] < 0:
                return False
            if manifest["after"] > manifest["snapshot"]:
                return False
            limit = manifest["limit"]
            if not _is_int(limit) or not 1 <= limit <= 200:
                return False
            if not _is_int(manifest["count"]) or manifest["count"] < 0:
                return False
            if (
                not isinstance(manifest["signer_did"], str)
                or not manifest["signer_did"]
            ):
                return False
            if not _is_int(manifest["key_version"]) or manifest[
                "key_version"
            ] < 1:
                return False
            if (
                not isinstance(manifest["signature"], str)
                or not manifest["signature"]
            ):
                return False

            events = manifest["events"]
            if not isinstance(events, list):
                return False
            if len(events) != manifest["count"] or len(events) > limit:
                return False
            previous_seq: Optional[int] = None
            for event in events:
                if not isinstance(event, dict):
                    return False
                if set(event) != set(self._AUDIT_EVENT_FIELDS):
                    return False
                if not _is_int(event["seq"]) or event["seq"] < 1:
                    return False
                if not _is_int(event["timestamp"]):
                    return False
                for field in (
                    "tenant_id",
                    "action",
                    "resource_type",
                    "resource_id",
                ):
                    if not isinstance(event[field], str) or not event[field]:
                        return False
                seq = event["seq"]
                if seq <= manifest["after"] or seq > manifest["snapshot"]:
                    return False
                if previous_seq is not None and seq <= previous_seq:
                    return False
                previous_seq = seq
            return True

        def _post_audit_manifest_verify(self, tenant: str) -> None:
            # POST /v1/audit/manifest/verify：只读验真审计签名清单。
            # 请求体须恰含 {"manifest": 对象}，结构缺失、多余字段、
            # 类型错误或非法 JSON 一律 400 且仅 {"error": 非空中文}。
            # 外层合法后任何失败均 HTTP 200，按序返回
            # {"valid":false,"reason":...}：清单非法 -> 锚点不可用
            # （本租户同 did/版本且含 generic 用途的 active 锚点）->
            # 签名格式错误 -> 签名校验失败。成功仅 {"valid":true}。
            # 纯只读：不查本地审计原文、不写状态或审计。
            data = self._read_json()
            if set(data) != {"manifest"}:
                if "manifest" not in data:
                    raise ValidationError("请求缺少字段: manifest")
                extra = sorted(set(data) - {"manifest"})
                raise ValidationError(f"请求含多余字段: {', '.join(extra)}")
            manifest = data["manifest"]
            if not isinstance(manifest, dict):
                raise ValidationError(
                    "请求不合法: 字段 manifest 必须为 JSON 对象"
                )

            reason = self._verify_audit_manifest_item(tenant, manifest)
            if reason is not None:
                self._send_invalid(reason)
                return
            self._send_json(200, {"valid": True})

        def _verify_audit_manifest_item(
            self,
            tenant: str,
            manifest: Any,
            anchor_snapshot: Optional[
                Dict[Tuple[str, int], Optional[str]]
            ] = None,
        ) -> Optional[str]:
            # 单项审计签名清单验真（供单项与批量端点共用）：按序返回
            # 失败原因（清单非法 -> 锚点不可用 -> 签名格式错误 ->
            # 签名校验失败），成功返回 None。锚点须为本租户同
            # did/版本 active 且含 generic 用途。anchor_snapshot 给定时
            # 为批量端点在批初原子取得的本租户锚点快照（键 did/版本，
            # 值为公钥 PEM 或 None），不再即时读锚点；为 None 时按单项
            # 协议即时读取。纯只读：不查本地审计原文、不写状态或审计。
            # 阶段一：清单结构（含事件范围与 count 行数一致性）
            if not self._audit_manifest_is_well_formed(manifest):
                return "清单非法"

            signer_did = manifest["signer_did"]
            key_version = manifest["key_version"]
            # 阶段二：本租户同 did/版本且含 generic 用途的 active 锚点
            if anchor_snapshot is None:
                public_pem = store.get_active_trust_anchor_public_key(
                    tenant, signer_did, key_version, required_use="generic"
                )
            else:
                public_pem = anchor_snapshot[(signer_did, key_version)]
            if public_pem is None:
                return "锚点不可用"
            try:
                crypto.validate_public_key_pem(public_pem)
            except (ValueError, TypeError):
                return "锚点不可用"

            signed = {
                "snapshot": manifest["snapshot"],
                "after": manifest["after"],
                "limit": manifest["limit"],
                "count": manifest["count"],
                "events": manifest["events"],
                "signer_did": signer_did,
                "key_version": key_version,
            }
            signature = manifest["signature"]
            # 阶段三：签名编码格式
            try:
                crypto.validate_signature_format_strict(signature)
            except crypto.MalformedSignature:
                return "签名格式错误"
            # 阶段四：ES256 裸签名密码学验签（锁外执行）
            try:
                crypto.verify(signed, signature, public_pem)
            except crypto.MalformedSignature:
                return "签名格式错误"
            except crypto.InvalidSignature:
                return "签名校验失败"
            except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露细节
                return "签名校验失败"
            return None

        def _post_audit_manifest_verify_batch(self, tenant: str) -> None:
            # POST /v1/audit/manifest/verify-batch：批量校验外系统交付
            # 的一批审计签名清单。任何失败都返回 HTTP 200。请求体须恰为
            # {"items": [项...]}，数组非空且不超过 100 项；空体、非法
            # JSON、非对象、外层字段缺失或多余、items 非数组、空数组或
            # 超限一律按键序恰返
            # {"results": [], "reason": "请求非法"}。合法批次返回
            # {"results": [...]}，长度与顺序与输入一致，逐项不短路；每项
            # 须恰含 manifest 对象，项非对象、字段或类型非法、清单内容
            # 或事件范围不合规按“清单非法”处理，其余复用单项验真协议
            # （锚点不可用 -> 签名格式错误 -> 签名校验失败）。成功项仅
            # {"valid": true}，失败项键序恰为 valid、reason。批初在同一
            # 把锁内原子读取本租户锚点快照（required_use 恒为
            # generic），锁外逐项验签；批内并发吊销或用途收紧不会产生
            # 混合结论。纯只读：不查本地审计原文、不写锚点、状态、游标
            # 或审计，结论跨重启稳定。
            def _request_invalid() -> None:
                self._send_json(
                    200, {"results": [], "reason": "请求非法"}
                )

            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                _request_invalid()
                return
            except Exception:  # noqa: BLE001
                _request_invalid()
                return
            if not raw:
                _request_invalid()
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, ValueError):
                # ValueError 含 JSON 解析错误与超长十进制整数位数上限。
                _request_invalid()
                return
            if not isinstance(data, dict) or set(data) != {"items"}:
                _request_invalid()
                return
            items = data["items"]
            if (
                not isinstance(items, list)
                or not items
                or len(items) > 100
            ):
                _request_invalid()
                return

            # 先判定每项外层结构与清单结构，收集结构合法项的锚点查询，
            # 批初在同一把锁内原子取得本租户锚点快照。
            well_formed: List[bool] = []
            queries: List[Tuple[str, int, str]] = []
            for item in items:
                if (
                    isinstance(item, dict)
                    and set(item) == {"manifest"}
                    and isinstance(item["manifest"], dict)
                    and self._audit_manifest_is_well_formed(item["manifest"])
                ):
                    well_formed.append(True)
                    queries.append(
                        (
                            item["manifest"]["signer_did"],
                            item["manifest"]["key_version"],
                            "generic",
                        )
                    )
                else:
                    well_formed.append(False)

            snapshot_pems = (
                store.get_active_trust_anchor_public_key_snapshot(
                    tenant, queries
                )
                if queries
                else []
            )
            anchor_snapshot: Dict[Tuple[str, int], Optional[str]] = {}
            for (did, key_version, _use), public_pem in zip(
                queries, snapshot_pems
            ):
                anchor_snapshot[(did, key_version)] = public_pem

            results: List[Dict[str, Any]] = []
            for index, item in enumerate(items):  # 顺序校验，失败不短路
                if not well_formed[index]:
                    results.append({"valid": False, "reason": "清单非法"})
                    continue
                reason = self._verify_audit_manifest_item(
                    tenant,
                    item["manifest"],
                    anchor_snapshot=anchor_snapshot,
                )
                if reason is None:
                    results.append({"valid": True})
                else:
                    results.append({"valid": False, "reason": reason})
            self._send_json(200, {"results": results})

    return Handler


class _ReadyServer(ThreadingHTTPServer):
    """确定性端口生命周期的 HTTP 服务。

    - allow_reuse_address：退出后同端口立即可再次绑定；
    - daemon_threads：活动请求线程不阻塞进程退出；
    - 绑定失败时关闭已创建的监听套接字，不残留监听。
    """

    allow_reuse_address = True
    daemon_threads = True

    def server_bind(self) -> None:
        try:
            super().server_bind()
        except OSError:
            try:
                self.socket.close()
            except OSError:
                pass
            raise


def _oserror_chinese(what: str, exc: OSError) -> str:
    """把 OSError 映射为单行中文原因。"""
    code = getattr(exc, "errno", None)
    if code is not None:
        if code == errno.EADDRINUSE:
            return f"{what}地址已被占用"
        if code == errno.EACCES:
            return f"{what}权限不足"
        return f"{what}失败（错误码 {code}）"
    return f"{what}失败"


def run(
    host: str = "127.0.0.1",
    port: int = 8080,
    store_path: Optional[str] = None,
    quiet: bool = False,
) -> None:
    """启动 HTTP 服务（阻塞至 Ctrl-C 后返回 None）。

    参数非法抛 ValueError；绑定或状态文件 I/O 失败抛 OSError；状态
    JSON 不可解析抛 ValueError。任何失败路径都不输出 READY 行且不
    残留监听套接字。绑定成功后向 stdout 输出一行：
    ``VCBACKEND_READY host=<host> port=<实际端口>``（port=0 时报告
    内核分配的实际端口），UTF-8 编码并 flush。
    """
    # ---- 参数校验（先于任何副作用） -------------------------------- #
    if not isinstance(host, str) or not host:
        raise ValueError("host 必须为非空字符串")
    if isinstance(port, bool) or not isinstance(port, int):
        raise ValueError("port 必须为整数")
    if not 0 <= port <= 65535:
        raise ValueError("port 必须在 0 到 65535 之间")
    if store_path is not None and not isinstance(store_path, str):
        raise ValueError("store_path 必须为 None 或字符串")

    # ---- 加载状态文件（先绑定，失败时尚无监听套接字） -------------- #
    try:
        store = VCStore(store_path)
    except (ValueError, TypeError, AttributeError) as exc:
        # json.JSONDecodeError 本身是 ValueError 子类；损坏的字段值
        # （int() 失败等）与结构畸形（顶层非对象）同样归为状态不可解析。
        message = str(exc).strip() or "状态文件内容无法解析"
        message = message.replace("\r", " ").replace("\n", " ").strip()
        raise ValueError(f"状态文件不是合法 JSON：{message}") from exc
    except OSError as exc:
        raise OSError(
            f"状态文件读取失败：{_oserror_chinese('读取状态文件', exc)}"
        ) from exc

    handler = build_handler(store)
    if quiet:
        handler.log_message = lambda *args, **kwargs: None  # noqa: E731

    # ---- 绑定监听端口 ---------------------------------------------- #
    try:
        httpd = _ReadyServer((host, port), handler)
    except OSError as exc:
        raise OSError(
            f"监听地址绑定失败：{_oserror_chinese('绑定监听地址', exc)}"
        ) from exc

    actual_port = int(httpd.server_address[1])
    try:
        sys.stdout.buffer.write(
            f"VCBACKEND_READY host={host} port={actual_port}\n".encode("utf-8")
        )
        sys.stdout.buffer.flush()
    except (AttributeError, OSError):
        # 极端环境下 stdout 无 buffer（如测试替身）：退回文本接口。
        print(f"VCBACKEND_READY host={host} port={actual_port}", flush=True)

    # ---- 服务至 Ctrl-C：守护线程承担活动请求，不阻塞退出 ----------- #
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        return None
    finally:
        try:
            httpd.server_close()
        except OSError:
            pass
    return None

